const timeZone = 'Europe/Paris';
const parts = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date());
const part = (name) => parts.find((value) => value.type === name).value;
const today = `${part('year')}-${part('month')}-${part('day')}`;
const tomorrow = new Date(`${today}T00:00:00Z`);
tomorrow.setUTCDate(tomorrow.getUTCDate() + 1);
const endDate = tomorrow.toISOString().slice(0, 10);
const offsetAt = (date) => {
  const value = new Intl.DateTimeFormat('en-US', { timeZone, timeZoneName: 'longOffset' }).formatToParts(date).find((item) => item.type === 'timeZoneName').value;
  const match = value.match(/^GMT(?:([+-])(\d{2}):(\d{2}))?$/);
  if (!match) throw new Error(`Fuseau horaire non reconnu : ${value}`);
  return match[1] ? (match[1] === '+' ? 1 : -1) * (Number(match[2]) * 60 + Number(match[3])) * 60000 : 0;
};
const midnight = (date) => {
  const [year, month, day] = date.split('-').map(Number);
  const target = Date.UTC(year, month - 1, day);
  let guess = target;
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const next = target - offsetAt(new Date(guess));
    if (next === guess) break;
    guess = next;
  }
  return new Date(guess).toISOString();
};
return [{ json: { timeMin: midnight(today), timeMax: midnight(endDate), date: today } }];

const calendars = ($json.items || []).filter((calendar) => ['owner', 'writer', 'reader'].includes(calendar.accessRole));
if (!calendars.length) throw new Error('Aucun calendrier lisible trouvé dans Google Calendar.');
const range = $('Préparer la journée').first().json;
return calendars.map((calendar) => ({ json: { calendar_id: calendar.id, calendar_name: calendar.summary || (calendar.primary ? 'Principal' : 'Sans nom'), timeMin: range.timeMin, timeMax: range.timeMax } }));

const excludedRecurringTitles = new Set(['danse sarah', 'gym emma']);
const currentDate = $('Préparer la journée').first().json.date;

const addDaysToDateStr = (dateStr, days) => {
  const [year, month, day] = dateStr.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
};

const getParisDateStr = (dateTimeStr) => {
  const timeZone = 'Europe/Paris';
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date(dateTimeStr));
  const part = (name) => parts.find((value) => value.type === name).value;
  return `${part('year')}-${part('month')}-${part('day')}`;
};

const events = $input.all().map((item) => item.json).filter((event) => {
  if (!event || !event.start) return false;
  const isRecurring = Boolean(event.recurringEventId || (Array.isArray(event.recurrence) && event.recurrence.length));
  const titleIsExcluded = excludedRecurringTitles.has(String(event.summary || '').trim().toLocaleLowerCase());
  if (isRecurring && titleIsExcluded) return false;

  if (event.start.date && event.end && event.end.date) {
    const startDate = event.start.date;
    const lastRealDate = addDaysToDateStr(event.end.date, -1);
    if (lastRealDate > startDate) {
      if (currentDate !== startDate && currentDate !== lastRealDate) return false;
    }
    return true;
  }

  if (event.start.dateTime && event.end && event.end.dateTime) {
    const startDateStr = getParisDateStr(event.start.dateTime);
    const endDateStr = getParisDateStr(event.end.dateTime);
    if (endDateStr !== startDateStr) {
      if (currentDate !== startDateStr && currentDate !== endDateStr) return false;
    }
    return true;
  }

  return true;
});
if (!events.length) return [];
events.sort((left, right) => new Date(left.start.dateTime || `${left.start.date}T00:00:00Z`).getTime() - new Date(right.start.dateTime || `${right.start.date}T00:00:00Z`).getTime());
const formatDate = (date) => new Intl.DateTimeFormat('fr-FR', { timeZone: 'UTC', day: '2-digit', month: '2-digit', year: 'numeric' }).format(new Date(`${date}T12:00:00Z`));
const classify = (event) => {
  const normalize = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase();
  const title = normalize(event.summary);
  const calendar = normalize(event.calendar_name);
  if (event.eventType === 'birthday' || /\b(anniversaire|birthday)\b/.test(title)) return 'birthday';
  if (event.eventType === 'holiday' || /\b(fetes?|jours? feries?|holidays?)\b/.test(`${title} ${calendar}`)) return 'holiday';
  return 'event';
};
const lines = events.map((event) => {
  const when = event.start.date
    ? `${formatDate(event.start.date)} (journée entière)`
    : new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Paris', weekday: 'short', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).format(new Date(event.start.dateTime));
  const location = event.location ? ` - ${event.location}` : '';
  const line = `${when} · ${event.calendar_name} · ${event.summary || '(sans titre)'}${location}`;
  const kind = classify(event);
  if (kind === 'birthday') return `🎂 _${line}_`;
  if (kind === 'holiday') return `🎉 _${line}_`;
  return `📌 *${line}*`;
});
const date = $('Préparer la journée').first().json.date;
const dateLabel = new Intl.DateTimeFormat('fr-FR', { timeZone: 'UTC', day: '2-digit', month: '2-digit', year: 'numeric' }).format(new Date(`${date}T12:00:00Z`));
return [{ json: { text: `📅 *Événements du ${dateLabel} :*\n${lines.join('\n')}` } }];

const rows = $input.all().map((item) => item.json || {}).filter((row) => String(row.remoteJid || '').trim());
if (rows.length !== 1) throw new Error(`Groupe MyBot Home introuvable ou ambigu dans whatsapp_group_name (${rows.length} résultat(s)).`);
const recipient = String(rows[0].remoteJid).trim();
if (!recipient.endsWith('@g.us')) throw new Error('Le remoteJid de MyBot Home n’est pas un identifiant de groupe valide.');
const text = $('Préparer le message').first().json.text;
return [{ json: { recipient, text, delay: 0 } }];
